def transform(grid):
    """Restore zeros in a cyclic column pattern with a diagonal predecessor."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The background repeats horizontally. Exclude the special main diagonal,
    # whose cells are shifted one step backward from the background sequence.
    background = []
    for c in range(w):
        values = [grid[r][c] for r in range(h)
                  if grid[r][c] != 0 and r != c]
        background.append(Counter(values).most_common(1)[0][0] if values else None)

    period = w
    for p in range(1, w + 1):
        if all(background[c] is None or background[c] == background[c % p]
               for c in range(w)):
            period = p
            break

    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                if r == c:
                    out[r][c] = background[(c - 1) % period]
                else:
                    out[r][c] = background[c % period]
    return out


