def transform(grid):
    """Fill masked cells in a diagonal-shifted cyclic row pattern."""
    h, w = len(grid), len(grid[0])

    # Below the diagonal, each column contains its unshifted background value.
    base = [None] * w
    for c in range(w):
        vals = [grid[r][c] for r in range(c + 1, h) if grid[r][c] != 0]
        if vals:
            base[c] = Counter(vals).most_common(1)[0][0]

    # Infer the repeating period from the unshifted samples, then extend any
    # columns whose below-diagonal portion is masked or lies past the diagonal.
    period = None
    for p in range(1, w + 1):
        if all(v is None or base[i % p] is None or v == base[i % p]
               for i, v in enumerate(base)):
            # Require at least one observed comparison so a missing prefix
            # cannot make an arbitrary short period appear valid.
            observed = [(i, v) for i, v in enumerate(base) if v is not None]
            if any(i >= p for i, _ in observed):
                period = p
                break
    if period is None:
        period = w

    for c in range(w):
        if base[c] is None and base[c % period] is not None:
            base[c] = base[c % period]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                source = c if r > c else (c - 1) % period
                out[r][c] = base[source]
    return out


